import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    // Reads the next whitespace-separated token from stdin
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        HashMap<Integer, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) count.merge(nextInt(), 1, Integer::sum);
        int bestVal = 0, bestCnt = 0;
        for (Map.Entry<Integer, Integer> e : count.entrySet()) {
            int v = e.getKey(), c = e.getValue();
            // higher count wins; on a tie the smaller value wins
            if (c > bestCnt || (c == bestCnt && v < bestVal)) { bestVal = v; bestCnt = c; }
        }
        System.out.println(bestVal);
    }
}

